#include "bc-math-library.hh"

#include <string_view>

namespace GD::Bc::Library {
// The generated bytes have static lifetime and are only read by the -l loader.
auto text() -> std::string_view { return {source, sizeof(source) - 1}; }
}  // namespace GD::Bc::Library
